// TASK 19: Improved profanity filter (normalize before checking)
// =============================================
(function() {
    // Enhanced profanity check that normalizes text before matching
    window.isCleanTextV2 = function(text) {
        if (!text) return true;
        // Normalize: lowercase, strip numbers/special chars that substitute letters
        var normalized = text.toLowerCase()
            .replace(/0/g, 'o').replace(/1/g, 'i').replace(/3/g, 'e')
            .replace(/4/g, 'a').replace(/5/g, 's').replace(/7/g, 't')
            .replace(/\$/g, 's').replace(/@/g, 'a').replace(/!/g, 'i')
            .replace(/\*/g, '').replace(/_/g, '').replace(/-/g, '')
            .replace(/[^a-z\s]/g, '');

        var BLOCKED = ['fuck','shit','bitch','dick','cock','pussy','cunt','nigger','nigga','fag','faggot','retard','nazi','hitler','kkk','porn','hentai','rape','pedo',
            'spic','wetback','chink','gook','kike','towelhead','raghead','beaner','coon','darkie','jap','paki','wop',
            'slut','whore','cum','dildo','tits','nude','naked','milf','molest','suicide','terrorist','jihad','genocide','lynch',
            'maga','trump','biden','democrat','republican','antifa','qanon','wwg1wga','supremacy','acab',
            'blowjob','handjob','fingering','masturbat','threesome','gangbang','fetish','bondage','bdsm','kinky','horny',
            'erection','ejaculat','deepthroat','creampie','cuckold','dominatrix','escort','prostitut','hooker','stripper','camgirl','sexting','nudes'];
        var words = normalized.split(/\s+/);
        for (var i = 0; i < words.length; i++) {
            for (var j = 0; j < BLOCKED.length; j++) {
                if (words[i] === BLOCKED[j]) return false;
                if (BLOCKED[j].length >= 4 && words[i].indexOf(BLOCKED[j]) !== -1) return false;
            }
        }
        return true;
    };

    // Override the original if it exists
    if (typeof window.isCleanText !== 'undefined') {
        window._origIsCleanText = window.isCleanText;
        window.isCleanText = window.isCleanTextV2;
    }
})();

