// Badge tooltip positioning — uses fixed positioning to avoid overflow clipping
(function() {
    function positionTip(item) {
        var tip = item.querySelector('.badge-tooltip');
        if (!tip) return;
        var rect = item.getBoundingClientRect();
        var tipW = 240;
        var left = rect.left + rect.width / 2 - tipW / 2;
        if (left < 8) left = 8;
        if (left + tipW > window.innerWidth - 8) left = window.innerWidth - tipW - 8;
        tip.style.left = left + 'px';
        tip.style.width = tipW + 'px';
        if (window.innerWidth > 900) {
            tip.style.top = (rect.top - 8) + 'px';
            tip.style.transform = 'translateY(-100%)';
        } else {
            tip.style.top = (rect.bottom + 8) + 'px';
            tip.style.transform = 'none';
        }
    }
    document.addEventListener('mouseover', function(e) {
        var item = e.target.closest('.badge-item');
        if (item) positionTip(item);
    });
    document.addEventListener('click', function(e) {
        var item = e.target.closest('.badge-item');
        if (item) positionTip(item);
    });
})();

// ---- Trail Channel Highlights ----
// Highlights sidebar channels that are part of the user's current active trail
(function() {
    'use strict';

    function getActiveTrail() {
        if (typeof window.NACHO_TRAILS === 'undefined') return null;
        var passed = [];
        try { passed = JSON.parse(localStorage.getItem('btc_trail_passed') || '[]'); } catch(e) {}
        var progress = {};
        try { progress = JSON.parse(localStorage.getItem('btc_trail_progress') || '{}'); } catch(e) {}

        for (var i = 0; i < window.NACHO_TRAILS.length; i++) {
            var trail = window.NACHO_TRAILS[i];
            // Skip if already passed
            if (passed.indexOf(trail.id) !== -1) continue;
            // Check if prerequisite is met
            if (trail.requires && passed.indexOf(trail.requires) === -1) break;
            // This is the active trail
            return { trail: trail, progress: progress[trail.id] || [] };
        }
        return null; // All trails complete
    }

    function highlightTrailChannels() {
        var active = getActiveTrail();
        // Clear all existing highlights first
        document.querySelectorAll('.ch-btn').forEach(function(btn) {
            btn.removeAttribute('data-trail');
            btn.style.removeProperty('border-left');
            btn.style.removeProperty('border-left-color');
            var dot = btn.querySelector('.trail-dot');
            if (dot) dot.remove();
        });

        if (!active) return;

        var trailChannelIds = active.trail.channels.map(function(c) { return c.id; });
        var visitedIds = active.progress;

        document.querySelectorAll('.ch-btn').forEach(function(btn) {
            // Extract channel ID from onclick
            var onclick = btn.getAttribute('onclick') || '';
            var match = onclick.match(/go\(['"]([^'"]+)['"]/);
            if (!match) return;
            var chId = match[1];

            var idx = trailChannelIds.indexOf(chId);
            if (idx === -1) return;

            var visited = visitedIds.indexOf(chId) !== -1;
            var color = active.trail.color || '#f7931a';

            btn.setAttribute('data-trail', active.trail.id);
            btn.style.borderLeft = '3px solid ' + (visited ? 'rgba(34,197,94,0.6)' : color);

            // Add trail indicator dot
            var dot = document.createElement('span');
            dot.className = 'trail-dot';
            dot.title = active.trail.emoji + ' ' + active.trail.name + (visited ? ' ✓' : ' — ' + active.trail.channels[idx].why);
            dot.style.cssText = 'display:inline-block;width:8px;height:8px;border-radius:50%;margin-left:auto;flex-shrink:0;background:' + (visited ? '#22c55e' : color) + ';box-shadow:0 0 4px ' + (visited ? 'rgba(34,197,94,0.5)' : color.replace(')', ',0.5)').replace('rgb', 'rgba')) + ';';
            if (visited) dot.textContent = '';
            btn.style.display = 'flex';
            btn.style.alignItems = 'center';
            btn.appendChild(dot);
        });
    }

    // Run on load and periodically (trail progress can change mid-session)
    function init() {
        if (typeof window.NACHO_TRAILS === 'undefined') {
            setTimeout(init, 2000);
            return;
        }
        highlightTrailChannels();
        // Re-highlight when user navigates home
        var _origGoHome = window.goHome;
        if (_origGoHome) {
            window.goHome = function() {
                _origGoHome.apply(this, arguments);
                setTimeout(highlightTrailChannels, 500);
            };
        }
        // Also re-highlight after channel visits (trail progress may update)
        var _origGo = window.go;
        if (_origGo) {
            window.go = function() {
                var result = _origGo.apply(this, arguments);
                // Re-highlight after navigation settles
                setTimeout(highlightTrailChannels, 1000);
                return result;
            };
        }
    }

    window.highlightTrailChannels = highlightTrailChannels;
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() { setTimeout(init, 1500); });
    } else {
        setTimeout(init, 1500);
    }
})();

// ---- PVP Lobby Announce — Global Chat notification on entry ----
// Note: pvpAnswer is NOT patched here; pvp.js handles answer submission directly.
(function() {
    'use strict';
    var _origEnterPVP = null;
    var _pvpPatchAttempts = 0;
    function _tryPatchEnterPVP() {
        if (window._pvpEnterPatched) return;
        if (typeof window.enterPVPMode === 'function') {
            window._pvpEnterPatched = true;
            _origEnterPVP = window.enterPVPMode;
            window.enterPVPMode = function() {
                _origEnterPVP.apply(this, arguments);
                // Announce PVP lobby entry — post to Global Chat (visible, not hidden in News)
                var _pvpName = (typeof currentUser !== 'undefined' && currentUser && currentUser.username) ? currentUser.username : null;
                if (_pvpName && (typeof window.nachoPostToGlobalChat === 'function' || typeof window.nachoGlobalAnnounce === 'function')) {
                    var _fn = typeof window.nachoPostToGlobalChat === 'function' ? window.nachoPostToGlobalChat : window.nachoGlobalAnnounce;
                    _fn('⚔️ @' + _pvpName + ' just entered the PVP arena! Think you can beat them? ➡️ [Enter PVP Lobby](#pvp)');
                }
            };
        } else if (_pvpPatchAttempts < 20) {
            _pvpPatchAttempts++;
            setTimeout(_tryPatchEnterPVP, 2000);
        }
    }
    setTimeout(_tryPatchEnterPVP, 3000);
})();

// ---- Sidebar Reading Progress Indicators ----
(function() {
    // Add subtle progress bars to sidebar channel buttons
    // Runs after channels render and on navigation
    
    function updateSidebarProgress() {
        try {
            var progress = JSON.parse(localStorage.getItem('btc_channel_progress') || '{}');
            var buttons = document.querySelectorAll('.ch-btn');
            buttons.forEach(function(btn) {
                var onclick = btn.getAttribute('onclick') || '';
                var match = onclick.match(/go\('([^']+)'\)/);
                if (!match) return;
                var channelId = match[1];
                var pct = progress[channelId] || 0;
                
                // Remove existing progress bar if any
                var existing = btn.querySelector('.ch-progress');
                if (existing) existing.remove();
                
                if (pct > 0) {
                    var bar = document.createElement('div');
                    bar.className = 'ch-progress';
                    bar.style.cssText = 'position:absolute;bottom:0;left:0;height:2px;background:' + 
                        (pct >= 100 ? '#22c55e' : 'var(--accent,#f7931a)') + 
                        ';width:' + Math.min(pct, 100) + '%;border-radius:0 1px 0 0;transition:width 0.3s;opacity:0.7;';
                    btn.style.position = 'relative';
                    btn.style.overflow = 'hidden';
                    btn.appendChild(bar);
                    
                    // Add checkmark for 100%
                    if (pct >= 100 && !btn.querySelector('.ch-done')) {
                        var check = document.createElement('span');
                        check.className = 'ch-done';
                        check.style.cssText = 'position:absolute;right:6px;top:50%;transform:translateY(-50%);font-size:0.6rem;opacity:0.5;';
                        check.textContent = '\u2713';
                        btn.appendChild(check);
                    }
                }
            });
        } catch(e) {}
    }
    
    // Run on initial load
    setTimeout(updateSidebarProgress, 2000);
    
    // Re-run when navigating home or after channel loads
    var _origGoHome = window.goHome;
    if (_origGoHome) {
        window.goHome = function() {
            var result = _origGoHome.apply(this, arguments);
            setTimeout(updateSidebarProgress, 500);
            return result;
        };
    }
    
    // Also update after each channel visit
    var _origGoProg = window.go;
    if (_origGoProg) {
        window.go = function() {
            var result = _origGoProg.apply(this, arguments);
            setTimeout(updateSidebarProgress, 1000);
            return result;
        };
    }
    
    // Expose for manual refresh
    window.updateSidebarProgress = updateSidebarProgress;
})();

// =====================================================================
// EXPERIENCE MODE VISIBILITY — Phase 2 (v2 — robust timing)
// Handles dynamically-injected widgets via render hooks + MutationObserver.
// =====================================================================
(function() {

    // IDs to hide per mode
    var HIDE_IDS = {
        beginner: [
            'chatOverlayBtn', 'aiToolsBtn', 'dashboardFloatBtn', 'lbFloatBtn',
            'dailySpinBanner', 'em-quick-actions',
            'dailyChallengeCard', 'raidBossHomeCard',
            'donateSection', 'quoteOfDay', 'dailyChannel',
            'hotTopicsSectionWrapper'
        ],
        intermediate: [
            'chatOverlayBtn', 'aiToolsBtn', 'dashboardFloatBtn', 'lbFloatBtn',
            'dailyChallengeCard', 'raidBossHomeCard',
            'donateSection', 'quoteOfDay', 'dailyChannel',
            'hotTopicsSectionWrapper'
        ],
        advanced: []
    };

    function _getMode() {
        try { return localStorage.getItem('btc_experience_mode') || null; } catch(e) { return null; }
    }

    function _hideEl(el, mode) {
        if (!el) return;
        el.setAttribute('data-em-hidden', mode);
        el.style.setProperty('display', 'none', 'important');
    }

    function _restoreAll() {
        document.querySelectorAll('[data-em-hidden]').forEach(function(el) {
            el.style.removeProperty('display');
            el.removeAttribute('data-em-hidden');
        });
    }

    // Hide dynamic elements that may not exist yet at page load
    function applyDynamic(mode) {
        if (!mode || mode === 'advanced') return;
        var ids = HIDE_IDS[mode] || [];
        ids.forEach(function(id) { _hideEl(document.getElementById(id), mode); });
        // intermediate: also hide Nacho story button (beginner keeps it per spec)
        if (mode === 'intermediate') {
            _hideEl(document.getElementById('nachoStoryBtn'), mode);
        }
    }

    function applyMode(mode) {
        _restoreAll();
        if (!mode || mode === 'advanced') return;
        applyDynamic(mode);
    }

    function run() {
        var mode = _getMode();
        if (!mode) {
            var done = false;
            try { done = localStorage.getItem('btc_onboarding_done') === 'true'; } catch(e) {}
            if (done) { mode = 'advanced'; try { localStorage.setItem('btc_experience_mode','advanced'); } catch(e) {} }
            else return;
        }
        applyMode(mode);
    }

    window.applyExperienceModeVisibility = run;
    window._emApplyMode = applyMode;

    // Hook render functions so widgets hide immediately after being painted
    function hookRenders() {
        ['renderDailyChallenge','renderRaidBossHome'].forEach(function(fn) {
            var orig = window[fn];
            var hookKey = '_em_' + fn + '_hooked';
            if (!orig || window[hookKey]) return;
            window[hookKey] = true;
            window[fn] = function() {
                var r = orig.apply(this, arguments);
                var m = _getMode();
                if (m && m !== 'advanced') setTimeout(function(){ applyDynamic(m); }, 50);
                return r;
            };
        });
    }

    // Multi-pass timing: catches static elements fast, dynamic elements after render
    function schedule() {
        setTimeout(run, 200);   // floating buttons (static) — hide fast
        setTimeout(run, 1200);
        setTimeout(run, 3000);  // after mobile-ux.js 2500ms widget render
        setTimeout(run, 6000);  // safety net
        setTimeout(hookRenders, 400);
        setTimeout(hookRenders, 2000);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', schedule);
    } else {
        schedule();
    }

    // Hook goHome so widgets are re-hidden after navigation
    setTimeout(function() {
        if (window._emGoHomeHooked) return;
        var orig = window.goHome;
        if (!orig) return;
        window._emGoHomeHooked = true;
        window.goHome = function() {
            var r = orig.apply(this, arguments);
            setTimeout(run, 600);
            setTimeout(run, 3200);
            return r;
        };
    }, 3500);

    // MutationObserver: catches dynamically injected nodes (hotTopics, nachoStoryBtn)
    var _obs = null, _obsTimer = null;
    function startObserver() {
        if (_obs) return;
        var mode = _getMode();
        if (!mode || mode === 'advanced') return;
        _obs = new MutationObserver(function() {
            clearTimeout(_obsTimer);
            _obsTimer = setTimeout(function() {
                var m = _getMode();
                if (m && m !== 'advanced') applyDynamic(m);
            }, 200);
        });
        _obs.observe(document.body, { childList: true, subtree: true });
    }
    setTimeout(startObserver, 800);
    setTimeout(startObserver, 3500);
})();

// =====================================================================
// XP & BADGE TOAST SUPPRESSION — Phase 3
// In beginner/intermediate modes: suppress XP gain and badge toasts.
// XP and badges are still SILENTLY collected (awardPoints/checkBadges run normally).
// Only the visible toast/celebration is suppressed.
// =====================================================================
(function() {
    // Patterns that identify XP/badge toasts to suppress
    var XP_PATTERNS = [
        /^\+\d+ XP/i,           // "+25 XP - Reading: ..."
        /streak.*XP/i,          // "Day 7 streak! +X XP"
        /2X XP/i,               // "2X XP! Daily boost..."
        /overflow pts/i,        // "overflow pts redeemed"
        /daily cap/i,           // "Daily cap reached"
        /XP will sync/i,        // offline sync
        /XP - /i,               // generic "+N XP - reason"
        /badge earned/i,        // badge earned toast (non-modal)
        /🏅.*earned/i,
        /earned.*🏅/i,
        /\+\d+ pts.*badge/i,
        /Nacho Quest.*pts/i,    // Nacho Quest XP toasts
        /WAGMI.*topic/i,        // Nacho Quest step toasts
        /First message sent/i,
        /Spin complete/i,
        /Smart question.*already/i,
    ];

    function shouldSuppress(msg) {
        if (typeof msg !== 'string') return false;
        for (var i = 0; i < XP_PATTERNS.length; i++) {
            if (XP_PATTERNS[i].test(msg)) return true;
        }
        return false;
    }

    function isQuietMode() {
        var m = null;
        try { m = localStorage.getItem('btc_experience_mode'); } catch(e) {}
        return (m === 'beginner' || m === 'intermediate');
    }

    setTimeout(function() {
        var _origToast = window.showToast;
        if (!_origToast || window._emToastHooked) return;
        window._emToastHooked = true;
        window.showToast = function(msg) {
            if (isQuietMode() && shouldSuppress(msg)) {
                // Silently drop — XP has already been awarded to Firestore/localStorage
                return;
            }
            return _origToast.apply(this, arguments);
        };
    }, 1500);

    // Suppress badge celebration MODAL in quiet modes 
    // (checkBadges still runs, badge is still stored — just no confetti/modal)
    setTimeout(function() {
        var _origCheck = window.checkBadges;
        if (!_origCheck || window._emBadgeHooked) return;
        window._emBadgeHooked = true;
        window.checkBadges = function(data, silent) {
            if (isQuietMode()) {
                // Force silent=true so checkBadges records the badge but skips celebration
                return _origCheck.call(this, data, true);
            }
            return _origCheck.apply(this, arguments);
        };
    }, 2000);
})();

// =====================================================================
// DESKTOP SIDEBAR LEARN + APPS — mode filtering
// Hides specific desktop buttons based on experience mode
// =====================================================================
(function() {
    function applyDesktopMenuModes() {
        var mode = null;
        try { mode = localStorage.getItem('btc_experience_mode'); } catch(e) {}
        if (!mode || mode === 'advanced') {
            // Show everything — remove any previous hiding
            document.querySelectorAll('[data-em-desk-hidden]').forEach(function(el) {
                el.style.display = '';
                el.removeAttribute('data-em-desk-hidden');
            });
            return;
        }

        // Desktop Learn menu: which buttons to HIDE per mode
        // Beginner: hide Daily Quests, Meetup Builder, Spend Bitcoin
        // Intermediate: nothing extra to hide in learn (has all)
        var LEARN_HIDE_ONCLICK = {
            beginner: ['showQuestHub', 'irl-sync', "section:'merchants'"],
            intermediate: []
        };

        // Desktop Explore Apps: beginner sees only Nacho Mode and Timechain TV
        var APPS_HIDE_ONCLICK = {
            beginner: ['enterProofOfPlay', "go('forum')", "go('marketplace')", "go('irl-sync')", "go('bitcoin-beats')", 'showProofOfWalk'],
            intermediate: []
        };

        var learnHide = LEARN_HIDE_ONCLICK[mode] || [];
        var appsHide = APPS_HIDE_ONCLICK[mode] || [];

        // Apply to homeLearnMenu buttons
        var learnMenu = document.getElementById('homeLearnMenu');
        if (learnMenu) {
            learnMenu.querySelectorAll('button').forEach(function(btn) {
                var oc = btn.getAttribute('onclick') || '';
                var shouldHide = learnHide.some(function(pat) { return oc.indexOf(pat) !== -1; });
                if (shouldHide) {
                    btn.setAttribute('data-em-desk-hidden', mode);
                    btn.style.display = 'none';
                } else {
                    btn.removeAttribute('data-em-desk-hidden');
                    btn.style.display = '';
                }
            });
        }

        // Apply to homeAppsMenu buttons
        var appsMenu = document.getElementById('homeAppsMenu');
        if (appsMenu) {
            appsMenu.querySelectorAll('button,[onclick]').forEach(function(btn) {
                var oc = btn.getAttribute('onclick') || '';
                var shouldHide = appsHide.some(function(pat) { return oc.indexOf(pat) !== -1; });
                if (shouldHide) {
                    btn.setAttribute('data-em-desk-hidden', mode);
                    btn.style.display = 'none';
                } else {
                    btn.removeAttribute('data-em-desk-hidden');
                    btn.style.display = '';
                }
            });
        }
    }

    // Run after menus are populated (toggleSidebarMenu populates them lazily)
    setTimeout(applyDesktopMenuModes, 1000);

    // Hook toggleSidebarMenu so filtering applies every time menu opens
    setTimeout(function() {
        var _orig = window.toggleSidebarMenu;
        if (!_orig || window._emSidebarHooked) return;
        window._emSidebarHooked = true;
        window.toggleSidebarMenu = function(id) {
            var r = _orig.apply(this, arguments);
            if (id === 'homeLearnMenu' || id === 'homeAppsMenu') {
                setTimeout(applyDesktopMenuModes, 50);
            }
            return r;
        };
    }, 2000);
    
    window.applyDesktopMenuModes = applyDesktopMenuModes;
})();
